const $=s=>document.querySelector(s),stage=$('#stage'),canvas=document.createElement('canvas'),c=canvas.getContext('2d');stage.append(canvas);
const keys=new Set(),pressed=new Set(),images={},blueImages={},effects=[];
let frames={},sim=new Duel(),state='loading',character='goku',arena='namek',time=0,last=performance.now(),accumulator=0,ready=false,frame=0,sound=false,audio=null,shake=0,flash=0,cutin=null,hudTime=0,ladder=0;
const reduce=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
