document.title='Dragon Ball Sprite Arena — Princewill Okube';$('#game-title').textContent='Dragon Ball Sprite Arena';$('#game-genre').textContent='2D SPRITE FIGHTER';$('#start-title').textContent='Dragon Ball Sprite Arena';
