$('#build-copy').innerHTML=`<p class="overline">ORIGINAL COMBAT ENGINE / CREDITED PIXEL ART</p><h2>From first punch to final flash.</h2><p>A new fixed-step Canvas 2D fighter. This compact fan game contains Goku and Vegeta, three arenas, arcade progression, training and local versus. It does not reproduce Dragon Ball Devolution’s full roster.</p><ol><li><h3>Move timing and combos</h3><p>Every punch, kick, uppercut and finisher has startup, active and recovery phases. Buffered inputs, hitstun, knockback, guard breaks and scaled combo damage control the fighting sequence. Land three hits, then J delivers a heavy finisher. S+J launches an uppercut.</p></li><li><h3>Ki, beams and transformation</h3><p>I fires a ki projectile. Hold O to charge Kamehameha (Goku) or Galick Gun (Vegeta); release to fire. U spends 80 ki on a character-specific ultimate. Opposing beams clash. T advances through Super Saiyan (60 ki), Super Saiyan 2 (80), then Blue (95). C charges ki. The golden sprites are from the original sheets; SS2 uses added lightning and Blue is a custom runtime palette variation.</p></li><li><h3>Play with a friend</h3><p>Player one uses WASD and the controls above. Player two uses arrow keys to move/fly, Numpad 8 jump, 4 flight, 1 punch, 2 kick, 3 blast, 0 guard, 5 charge, 7 transform, 6 beam, 9 ultimate, decimal teleport and right Shift dash. A keyboard with numpad is required for local versus.</p></li><li><h3>Sprite credits</h3><p>Goku and Vegeta sheets: <a href="https://github.com/MitchStreet/2D-Dragonball-Game" target="_blank" rel="noopener">Mitchell Jay Street’s public project</a>; source game Dragon Ball Z: Legendary Super Warriors. Rippers Jay Ibero (Yajirobe), Majin Aussie, Grim and Bonzai. Edits/colour correction Son Goharotto / enpitsudo-dojo.com. Source-sheet credits are preserved.</p></li></ol><p class="build-note">Original fan-game implementation. Character names and source art belong to their respective owners. Promotional cover artwork is illustrative.</p>`;
const next=document.createElement('button');next.id='next-arena';next.className='primary';next.hidden=true;next.textContent='Next arena →';$('#end-panel .panel-actions').prepend(next);
const menu=document.createElement('button');menu.textContent='Fighter / mode select';menu.onclick=()=>{state='ready';$('#end-panel').hidden=true;$('#start-panel').hidden=false};$('#end-panel .panel-actions').append(menu);
function tone(freq=440,duration=.1,type='sine'){if(!sound)return;const A=window.AudioContext||window.webkitAudioContext;if(!A)return;audio??=new A();audio.resume().catch(()=>{});const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(40,freq*.4),audio.currentTime+duration);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
function announce(text){$('#game-message').textContent=text;$('#game-message').classList.add('on');clearTimeout(announce.timer);announce.timer=setTimeout(()=>$('#game-message').classList.remove('on'),1800)}
function sprite(ctx,name,kind,x,y,height,face=1,form=0,t=0,action=null){
 const group=frames[name];if(!group)return;let list=group[(form?'ss':'')+kind]||group[kind]||group.idle;
 if(kind==='attack'&&list.length>3){const slices={punch:[0,3],kick:[3,6],heavy:[6,9],uppercut:[9,12]},range=slices[action?.type]||[0,3];list=list.slice(range[0],Math.min(range[1],list.length));if(!list.length)list=group.attack}
 const ix=action?Math.min(list.length-1,Math.floor(action.progress*list.length)):Math.floor(t*(kind==='run'?12:8))%list.length;
 const [sx,sy,w,h]=list[ix],scale=height/46;ctx.save();ctx.translate(Math.round(x),Math.round(y));if(face<0)ctx.scale(-1,1);ctx.imageSmoothingEnabled=false;ctx.drawImage(form===3&&blueImages[name]?blueImages[name]:images[name],sx,sy,w,h,-w*scale/2,-h*scale,w*scale,h*scale);ctx.restore();
}
function makeBlue(name){const sheet=images[name],im=document.createElement('canvas');im.width=sheet.naturalWidth||sheet.width;im.height=sheet.naturalHeight||sheet.height;const ctx=im.getContext('2d',{willReadFrequently:true});if(!im.width||!ctx.getImageData)return;ctx.drawImage(sheet,0,0);const data=ctx.getImageData(0,0,im.width,im.height);for(let i=0;i<data.data.length;i+=4){const r=data.data[i],g=data.data[i+1],b=data.data[i+2];if(r>130&&g>r*.8&&b<Math.min(r,g)*.65){data.data[i]=Math.min(150,b+30);data.data[i+1]=Math.min(245,g+35);data.data[i+2]=Math.min(255,r+25)}}ctx.putImageData(data,0,0);blueImages[name]=im}
function resize(){const r=stage.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,r.width*dpr);canvas.height=Math.max(1,r.height*dpr)}window.addEventListener('resize',resize);resize();
function aura(f,x,y){const color=FORMS[f.form].color,charge=f.charging||f.beamCharge>0||f.transformTime>0;if(!f.form&&!charge)return;c.save();c.globalAlpha=f.transformTime?.4:.18;c.fillStyle=color;const radius=charge?38:27;c.beginPath();c.moveTo(x-radius,y);for(let i=0;i<=12;i++){const a=Math.PI+i*Math.PI/12,px=x+Math.cos(a)*(radius+Math.sin(time*12+i*2)*6),py=y+Math.sin(a)*125;c.lineTo(px,py)}c.closePath();c.fill();c.globalAlpha=.5;c.strokeStyle=color;c.lineWidth=2;c.stroke();if(f.form>=2&&!reduce()){c.strokeStyle=f.form===3?'#d9faff':'#b6d4ff';c.lineWidth=1.7;for(let i=0;i<3;i++){const q=time*9+i*2;c.beginPath();c.moveTo(x+Math.sin(q)*30,y-95);c.lineTo(x+Math.sin(q+2)*35,y-65);c.lineTo(x+Math.sin(q+1)*20,y-35);c.stroke()}}c.restore()}
function render(){
 c.setTransform(1,0,0,1,0,0);c.fillStyle='#102338';c.fillRect(0,0,canvas.width,canvas.height);const scale=Math.min(canvas.width/960,canvas.height/540),ox=(canvas.width-960*scale)/2,oy=(canvas.height-540*scale)/2;c.setTransform(scale,0,0,scale,ox,oy);if(!reduce()&&shake>0)c.translate(Math.sin(time*80)*shake,Math.cos(time*95)*shake*.5);background(c,arena);
 sim.fighters.forEach((f,i)=>{const x=480+f.x*37,y=426-f.y*37,previous=f.lastX??f.x,moving=Math.abs(previous-f.x)>.005;f.lastX=f.x;const action=f.action?{type:f.action.type,progress:clamp(f.actionTime/(f.action.startup+f.action.active),0,1)}:null;
 let kind=f.stun?'misc':f.transformTime||f.charging||f.beamCharge?'charge':f.block?'guard':f.poseTime&&['blast','beam'].includes(f.pose)?'blast':action?'attack':f.flight||f.y>1?'flight':moving?'run':'idle';
 c.save();c.globalAlpha=.2;c.fillStyle='#091d26';c.beginPath();c.ellipse(x,432,24/(1+f.y*.1),5,0,0,Math.PI*2);c.fill();c.restore();aura(f,x,y);
 if(f.inv>0&&f.stun>0)c.globalAlpha=.6+Math.sin(time*90)*.3;sprite(c,names()[i],kind,x,y,108,f.face,f.form,time,action);c.globalAlpha=1;
 if(f.block){c.strokeStyle='#baf1ff99';c.lineWidth=2;c.beginPath();c.ellipse(x,y-48,32,53,0,0,Math.PI*2);c.stroke()}
 if(f.beamCharge){const bx=x+f.face*27,by=y-47;c.shadowColor=names()[i]==='goku'?'#57dfff':'#da8fff';c.shadowBlur=20;c.fillStyle=c.shadowColor;c.beginPath();c.arc(bx,by,7+f.beamCharge*8,0,Math.PI*2);c.fill();c.shadowBlur=0}
 });
 for(const beam of sim.beams){const x=480+beam.x*37,y=426-beam.y*37,end=480+(beam.stop??beam.face*13)*37;const color=names()[beam.owner]==='goku'?'#78eaff':beam.ultimate?'#ffe68a':'#b27aff';c.save();c.lineCap='round';c.shadowColor=color;c.shadowBlur=22;c.strokeStyle=color;c.globalAlpha=.65;c.lineWidth=beam.thickness*60*(1+Math.sin(time*44)*.08);c.beginPath();c.moveTo(x,y);c.lineTo(end,y);c.stroke();c.globalAlpha=1;c.strokeStyle='#f0fbff';c.lineWidth=beam.thickness*22;c.stroke();c.restore()}
 for(const b of sim.bolts){const x=480+b.x*37,y=426-b.y*37,color=names()[b.owner]==='goku'?'#80dfff':'#ffce6a';c.save();c.shadowColor=color;c.shadowBlur=15;c.fillStyle=color;c.beginPath();c.ellipse(x,y,12,7,0,0,Math.PI*2);c.fill();c.fillStyle='#fff';c.beginPath();c.ellipse(x+Math.sign(b.vx)*3,y,5,3,0,0,Math.PI*2);c.fill();c.globalAlpha=.45;c.fillStyle=color;c.fillRect(x-Math.sign(b.vx)*36,y-3,Math.sign(b.vx)*32,6);c.restore()}
 for(const e of effects){const alpha=clamp(e.life/e.max,0,1);c.save();c.globalAlpha=alpha;c.strokeStyle=e.color;c.lineWidth=e.kind==='teleport'?2:3;for(let i=0;i<8;i++){const a=i*Math.PI/4;c.beginPath();c.moveTo(e.x+Math.cos(a)*5,e.y+Math.sin(a)*5);c.lineTo(e.x+Math.cos(a)*(12+(1-alpha)*35),e.y+Math.sin(a)*(12+(1-alpha)*35));c.stroke()}c.restore()}
 if(!reduce()&&flash>0){c.fillStyle=`rgba(220,241,255,${Math.min(.18,flash)})`;c.fillRect(0,0,960,540)}
 if(cutin){c.fillStyle='#06162be8';c.fillRect(0,208,960,88);c.fillStyle='#e6f7ff';c.font='bold 30px system-ui';c.textAlign='center';c.fillText(cutin.text,480,262);c.textAlign='start'}
}
function hud(){const [p,e]=sim.fighters,fn=(f,i)=>`<div class="fighter-hud ${i?'rival':''}"><strong>${names()[i].toUpperCase()} <span>${'●'.repeat(sim.wins[i])}${'○'.repeat(2-sim.wins[i])}</span></strong><small>${FORMS[f.form].name}</small><div class="meter"><i style="width:${f.hp}%"></i></div><div class="meter ki-meter"><i style="width:${f.ki}%"></i></div><small>HP ${Math.ceil(f.hp)} · KI ${Math.floor(f.ki)} ${f.combo>1?'· '+f.combo+' HITS':''}</small><small>${f.form<3?'T: '+FORMS[f.form+1].name+' · '+FORMS[f.form+1].cost+' KI':'MAXIMUM FORM'}</small></div>`;$('#hud').innerHTML=fn(p,0)+`<div class="round-hud"><strong>${sim.mode==='training'?'∞':Math.ceil(sim.timer)}</strong><small>ROUND ${sim.round} · ${sim.mode.toUpperCase()}</small>${sim.delay>0?'<b>'+ (sim.roundWinner<0?'DRAW':names()[sim.roundWinner].toUpperCase()+' WINS')+'</b>':''}</div>`+fn(e,1)}
function start(advance=false){const opts=Object.fromEntries([...$('#start-options').querySelectorAll('select')].map(e=>[e.name,e.value]));if(!advance)ladder=0;sim=new Duel(opts);character=opts.fighter==='vegeta'?'vegeta':'goku';arena=advance?['namek','temple','space'][ladder]:opts.stage;state='playing';keys.clear();pressed.clear();effects.length=0;accumulator=0;shake=flash=0;cutin=null;next.hidden=true;for(const id of ['start-panel','end-panel','pause-panel','build-panel'])$('#'+id).hidden=true;stage.focus();announce('Round one · fight!');hud()}
function pause(){if(state==='playing'){state='paused';keys.clear();pressed.clear();$('#pause-panel').hidden=false;$('#resume').focus()}else if(state==='paused'){state='playing';$('#pause-panel').hidden=true;stage.focus()}}
function onEvent(e){if(['hit','block','clash','teleport'].includes(e.kind)){effects.push({kind:e.kind,x:480+e.x*37,y:426-e.y*37,max:.32,life:.32,color:e.kind==='block'?'#a2edff':'#ffe398'});if(e.kind==='hit'){shake=4;tone(180+e.combo*30,.07,'triangle')}if(e.kind==='clash')tone(80,.1,'sawtooth')}
 if(e.kind==='transform'){flash=.15;shake=3;announce(names()[e.owner].toUpperCase()+' · '+FORMS[e.form].name);tone(350,.65,'sawtooth')}
 if(e.kind==='beam'||e.kind==='ultimate'){const who=names()[e.owner],text=who==='goku'?(e.kind==='ultimate'?'SUPER KAMEHAMEHA!':'KAMEHAMEHA!'):(e.kind==='ultimate'?'FINAL FLASH!':'GALICK GUN!');announce(text);tone(e.kind==='ultimate'?130:240,.6,'sawtooth');if(e.kind==='ultimate')cutin={text,life:.65}}
 if(e.kind==='guard-break')announce('Guard broken!');if(e.kind==='fight')announce('Round '+e.round+' · fight!');if(e.kind==='round')announce(e.winner<0?'Draw · fight again!':names()[e.winner].toUpperCase()+' takes the round');}
function tick(now){const dt=clamp((now-last)/1000||0,0,.08);last=now;if(state==='playing'){time+=dt;accumulator+=dt;let steps=0;while(accumulator>=1/120&&steps++<10){const stopped=sim.hitstop>0;sim.update(1/120,keys,pressed);if(!stopped)pressed.clear();for(const event of sim.events)onEvent(event);accumulator-=1/120}for(const e of effects)e.life-=dt;for(let i=effects.length-1;i>=0;i--)if(effects[i].life<=0)effects.splice(i,1);shake=Math.max(0,shake-dt*22);flash=Math.max(0,flash-dt);if(cutin){cutin.life-=dt;if(cutin.life<=0)cutin=null}hudTime+=dt;if(hudTime>.05){hudTime=0;hud()}if(sim.over){state='ended';hud();const won=sim.winner===0;$('#end-title').textContent=won?'Victory!':'A rival worth another round.';$('#end-description').textContent=`${names()[sim.winner].toUpperCase()} wins ${Math.max(...sim.wins)}–${Math.min(...sim.wins)}.${sim.mode==='arcade'&&won?(ladder<2?' A new arena awaits.':' Arcade run complete!'):''}`;next.hidden=!(sim.mode==='arcade'&&won&&ladder<2);$('#end-panel').hidden=false;$('#restart').focus()}}
 if(ready)render();frame=requestAnimationFrame(tick)}
window.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea'))return;if(e.code==='Escape'||e.code==='KeyP'){e.preventDefault();if(!$('#build-panel').hidden){$('#build-panel').hidden=true;return}pause();return}if(state==='playing'){if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!keys.has(e.code))pressed.add(e.code);keys.add(e.code)}});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();pressed.clear();if(state==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause()});
$('#touch-controls').innerHTML=[['KeyA','←'],['KeyD','→'],['KeyW','↑'],['KeyS','↓'],['Space','Jump'],['KeyF','Fly'],['KeyJ','Punch'],['KeyK','Kick'],['KeyI','Ki'],['KeyO','Beam'],['KeyC','Charge'],['KeyL','Guard'],['KeyT','Form'],['KeyQ','Warp'],['KeyU','Super']].map(([k,t])=>`<button data-key="${k}">${t}</button>`).join('');
const touches=new Map();$('#touch-controls').addEventListener('pointerdown',e=>{const b=e.target.closest('[data-key]');if(!b||state!=='playing')return;e.preventDefault();b.setPointerCapture(e.pointerId);touches.set(e.pointerId,b);if(!keys.has(b.dataset.key))pressed.add(b.dataset.key);keys.add(b.dataset.key);b.classList.add('held')});for(const event of ['pointerup','pointercancel','lostpointercapture'])$('#touch-controls').addEventListener(event,e=>{const b=touches.get(e.pointerId);if(b){touches.delete(e.pointerId);if(![...touches.values()].includes(b)){keys.delete(b.dataset.key);b.classList.remove('held')}}});
$('#start-game').onclick=$('#restart').onclick=$('#pause-restart').onclick=()=>start();next.onclick=()=>{ladder++;start(true)};$('#pause-button').onclick=$('#resume').onclick=pause;$('#change-mode').onclick=()=>{state='ready';$('#pause-panel').hidden=true;$('#start-panel').hidden=false};const showBuild=()=>{if(state==='playing')pause();$('#build-panel').hidden=false};$('#build-button').onclick=showBuild;document.querySelectorAll('[data-build]').forEach(b=>b.onclick=showBuild);$('#build-close').onclick=()=>$('#build-panel').hidden=true;$('#sound-button').onclick=()=>{sound=!sound;$('#sound-button').textContent=sound?'Sound on':'Sound off';if(sound)tone()};$('#fullscreen-button').onclick=()=>document.fullscreenElement?document.exitFullscreen?.():document.documentElement.requestFullscreen?.().catch(()=>{});$('#return-button').onclick=()=>location.href='../../games.html';
Promise.all([fetch('assets/sprites/frames.json').then(r=>{if(!r.ok)throw Error('Frame map missing');return r.json()}),...['goku','vegeta'].map(name=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[name]=im;makeBlue(name);resolve()};im.onerror=reject;im.src='assets/sprites/'+name+'.png'}))]).then(([data])=>{frames=data;ready=true;state='ready';$('#start-game').disabled=false;$('#start-game').textContent='Let’s fight →';$('#load-status').textContent='Sprites ready · 3 modes · 4 forms · credits in build notes';pc.fillStyle='#203b55';pc.fillRect(0,0,400,360);sprite(pc,'goku','idle',110,285,220,1);sprite(pc,'vegeta','idle',295,285,220,-1);if(new URLSearchParams(location.search).get('build')==='1')showBuild()}).catch(()=>$('#load-status').textContent='Sprite loading failed. Reload to try again.');
window.GameDiagnostics={get state(){return state},get loaded(){return ready},get snapshot(){return {round:sim.round,hp:sim.fighters.map(f=>f.hp),wins:sim.wins,over:sim.over,forms:sim.fighters.map(f=>f.form),bolts:sim.bolts.length,beams:sim.beams.length,renderer:'Canvas 2D sprites'}}};window.addEventListener('pagehide',()=>{cancelAnimationFrame(frame);audio?.close().catch(()=>{})});frame=requestAnimationFrame(tick);
